import { test, expect } from '@playwright/test';

test.describe('Notifications Empty State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display empty state message when user has no notifications', async ({ page }) => {
    const emptyStateMessage = page.getByText(/no notifications/i);
    await expect(emptyStateMessage).toBeVisible();
  });

  test('should display empty state icon when notifications list is empty', async ({ page }) => {
    const emptyStateIcon = page.getByRole('img', { name: /empty notifications/i });
    await expect(emptyStateIcon).toBeVisible();
  });

  test('should display helpful text in empty state', async ({ page }) => {
    const helpfulText = page.getByText(/you're all caught up/i);
    await expect(helpfulText).toBeVisible();
  });

  test('should not display notification list when empty', async ({ page }) => {
    const notificationList = page.getByRole('list', { name: /notifications/i });
    await expect(notificationList).not.toBeVisible();
  });
});
